from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption(self.spy, Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.Strikes(-200, 200).Expiration(
                timedelta(days=0), timedelta(days=365)
            )
        )
        self.option_symbol = option.Symbol

        self.five_minute_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_group_end = None
        self.current_group_bars = []

        self.pending_entry_order_id = None
        self.pending_entry_symbol = None
        self.pending_entry_expiry = None

        self.held_contract = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.exit_order_id = None
        self.spy_liquidation_order_id = None
        self.expiration_exit_date = None

    def OnData(self, slice):
        self._handle_unexpected_spy_position()

        if self.held_contract is not None:
            quantity = self.Portfolio[self.held_contract].Quantity

            if quantity == 0 and self.exit_order_id is None:
                self.Debug(f"Option position no longer held: {self.held_contract}")
                self._clear_held_position()
            else:
                if self.Time.date() >= self.held_expiry:
                    self.expiration_exit_date = self.Time.date()
                    self._submit_option_exit("expiration processing")
                else:
                    self._check_profit_target(slice)
                    self._check_time_stop()

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_spy_minute_bar(spy_bar, slice)

    def _process_spy_minute_bar(self, bar, slice):
        bar_end = bar.EndTime
        session_start = datetime.combine(bar_end.date(), time(9, 30))
        session_end = datetime.combine(bar_end.date(), time(16, 0))

        if bar_end <= session_start or bar_end > session_end:
            return

        minutes_from_open = int((bar_end - session_start).total_seconds() // 60)
        group_number = (minutes_from_open + 4) // 5
        group_end = session_start + timedelta(minutes=group_number * 5)

        if self.current_group_end != group_end:
            self.current_group_end = group_end
            self.current_group_bars = []

        self.current_group_bars.append(bar)

        if bar_end != group_end:
            return

        expected_times = [
            group_end - timedelta(minutes=offset)
            for offset in range(4, -1, -1)
        ]
        actual_times = [minute_bar.EndTime for minute_bar in self.current_group_bars]

        if len(self.current_group_bars) == 5 and actual_times == expected_times:
            five_minute_close = self.current_group_bars[-1].Close
            self._on_completed_five_minute_bar(group_end, five_minute_close, slice)

        self.current_group_bars = []

    def _on_completed_five_minute_bar(self, bar_end, close, slice):
        self.five_minute_closes.append(close)

        if len(self.five_minute_closes) < 20:
            return

        closes = list(self.five_minute_closes)
        fast = sum(closes[-5:]) / 5.0
        slow = sum(closes[-20:]) / 20.0

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_crossover:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if self.expiration_exit_date == self.Time.date():
            return

        if self.held_contract is not None or self.pending_entry_order_id is not None:
            return

        self._select_and_submit_entry(slice, close)

    def _select_and_submit_entry(self, slice, spy_price):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"Skipped entry {self.Time}: no SPY option chain in Slice")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expiry_dates = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if contract.Expiry.date() >= minimum_expiry
            }
        )

        if not expiry_dates:
            self.Debug(f"Skipped entry {self.Time}: no expiration at least 7 calendar days away")
            return

        selected_expiry = expiry_dates[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Skipped entry {self.Time}: no qualifying call for expiry {selected_expiry}"
            )
            return

        selected = min(candidates, key=lambda contract: (contract.Strike, str(contract.Symbol)))

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.pending_entry_order_id = ticket.OrderId
        self.pending_entry_symbol = selected.Symbol
        self.pending_entry_expiry = selected_expiry
        self.Debug(
            f"Submitted call entry: {selected.Symbol}, expiry {selected_expiry}, "
            f"strike {selected.Strike}"
        )

    def _check_profit_target(self, slice):
        if self.exit_order_id is not None or self.entry_fill_price is None:
            return

        quote = slice.QuoteBars.get(self.held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self._submit_option_exit(
                f"50% profit target reached at midpoint {midpoint:.2f}"
            )

    def _check_time_stop(self):
        if self.exit_order_id is not None:
            return

        if self.Time.time() != time(15, 45):
            return

        if self.Time.date() == self._previous_trading_day(self.held_expiry):
            self._submit_option_exit("15:45 day-before-expiration time stop")

    def _previous_trading_day(self, expiry_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = expiry_date - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate, False):
            candidate -= timedelta(days=1)

        return candidate

    def _submit_option_exit(self, reason):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            self._clear_held_position()
            return

        for open_order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(open_order.Id, "Replacing with required market exit")

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Submitted option exit: {self.held_contract}; {reason}")

    def _handle_unexpected_spy_position(self):
        spy_quantity = self.Portfolio[self.spy].Quantity

        if spy_quantity == 0:
            return

        if self.spy_liquidation_order_id is not None:
            return

        ticket = self.MarketOrder(self.spy, -spy_quantity)
        self.spy_liquidation_order_id = ticket.OrderId
        self.Debug(
            f"Unexpected SPY position from exercise/assignment; liquidating {spy_quantity} shares"
        )

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.pending_entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = self.pending_entry_symbol
                self.held_expiry = self.pending_entry_expiry
                self.entry_fill_price = order_event.FillPrice
                self.pending_entry_order_id = None
                self.pending_entry_symbol = None
                self.pending_entry_expiry = None
                self.Debug(
                    f"Call entry filled: {self.held_contract} at {self.entry_fill_price:.2f}"
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Entry order not filled: {order_event.Message}")
                self.pending_entry_order_id = None
                self.pending_entry_symbol = None
                self.pending_entry_expiry = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Option exit filled: {self.held_contract} at {order_event.FillPrice:.2f}"
                )
                self._clear_held_position()
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Exit order not filled: {order_event.Message}")
                self.exit_order_id = None

        if order_event.OrderId == self.spy_liquidation_order_id:
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.spy_liquidation_order_id = None

    def _clear_held_position(self):
        self.held_contract = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.exit_order_id = None

