        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.five_minute_consolidator)

        self.pending_entry_signal_time = None

        self.entry_order_id = None
        self.entry_symbol = None
        self.entry_expiry = None
        self.entry_price = None

        self.held_symbol = None
        self.held_expiry = None

        self.exit_order_id = None
        self.exit_ticket = None
        self.spy_liquidation_order_id = None

        self.no_entry_date = None

    def OnFiveMinuteBar(self, bar):
        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = float(self.fast.Current.Value) if previous_ready else None
        previous_slow = float(self.slow.Current.Value) if previous_ready else None

        self.fast.Update(IndicatorDataPoint(bar.EndTime, bar.Close))
        self.slow.Update(IndicatorDataPoint(bar.EndTime, bar.Close))

        if not (previous_ready and self.fast.IsReady and self.slow.IsReady):
            return

        current_fast = float(self.fast.Current.Value)
        current_slow = float(self.slow.Current.Value)

        if previous_fast <= previous_slow and current_fast > current_slow:
            bar_time = bar.EndTime
            if (bar_time.hour, bar_time.minute) >= (9, 45) and \
               (bar_time.hour, bar_time.minute) <= (14, 30):
                self.pending_entry_signal_time = bar_time

    def OnData(self, data):
        self.HandleUnexpectedSpyEquityPosition()
        self.HandleExpirationSafety()

        if self.held_symbol is not None:
            self.EvaluateExit(data)

        if self.pending_entry_signal_time == self.Time:
            self.pending_entry_signal_time = None
            self.TryEnter(data)

        self.ClearClosedPositionState()

    def TryEnter(self, data):
        if self.no_entry_date == self.Time.date():
            return

        if self.entry_order_id is not None or self.exit_order_id is not None:
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        if self.spy not in data.Bars:
            self.Debug("Skipped entry: no current SPY bar")
            return

        chain = None
        try:
            chain = data.OptionChains[self.option_symbol]
        except KeyError:
            self.Debug("Skipped entry: no option chain")
            return

        current_spy_price = float(data.Bars[self.spy].Close)
        minimum_expiry = self.Time.date() + timedelta(days=7)

        expiries = sorted(
            {
                contract.Expiry.date()
                for contract in chain.Contracts.Values
                if contract.Expiry.date() >= minimum_expiry
            }
        )

        if not expiries:
            self.Debug("Skipped entry: no expiration at least seven calendar days out")
            return

        selected_expiry = expiries[0]
        minimum_strike = current_spy_price * 1.01

        candidates = [
            contract for contract in chain.Contracts.Values
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration")
            return

        selected = min(candidates, key=lambda contract: (float(contract.Strike), str(contract.Symbol)))

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.entry_symbol = selected.Symbol
        self.entry_expiry = selected.Expiry.date()

        self.Debug(
            "Entry submitted: {0} expiry {1} strike {2}".format(
                selected.Symbol,
                selected.Expiry.date(),
                selected.Strike
            )
        )

    def EvaluateExit(self, data):
        if self.exit_order_id is not None:
            return

        if not self.Portfolio[self.held_symbol].Invested:
            return

        if self.IsPreExpirationTimeStop():
            self.SubmitExit("pre-expiration time stop")
            return

        if self.entry_price is None or self.entry_price <= 0:
            return

        contract = self.GetHeldContractFromSlice(data)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitExit("50% profit target")

    def HandleExpirationSafety(self):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if self.Time.date() < self.held_expiry:
            return

        self.no_entry_date = self.Time.date()

        if self.Portfolio[self.held_symbol].Invested and self.exit_order_id is None:
            self.SubmitExit("expiration safety")

    def IsPreExpirationTimeStop(self):
        if self.held_expiry is None:
            return False

