        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal_time = None

        self.held_option = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_price = None
        self.blocked_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        crossed_up = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        bar_time = bar.EndTime.time()
        eligible_time = clock_time(9, 45) <= bar_time <= clock_time(14, 30)

        if crossed_up and eligible_time:
            self.pending_signal_time = bar.EndTime

    def OnData(self, data):
        self.HandleUnexpectedSpyEquity()

        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if self.Time.date() >= expiry_date:
                self.blocked_entry_date = self.Time.date()
                if self.Portfolio[self.held_option].Quantity != 0:
                    self.SubmitExit("expiration processing")
                else:
                    self.held_option = None
                    self.entry_price = None
                    self.exit_order_id = None

        self.SyncOptionState()
        self.EvaluateExits(data)

        if self.pending_signal_time is not None and self.pending_signal_time != self.Time:
            self.pending_signal_time = None

        if self.pending_signal_time == self.Time:
            self.pending_signal_time = None
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.blocked_entry_date == self.Time.date():
            self.Debug("Entry skipped: expiration processing day")
            return

        if self.held_option is not None or self.entry_order_id is not None:
            self.Debug("Entry skipped: option position or entry order already exists")
            return

        spot = self.Securities[self.spy].Price
        if spot <= 0:
            self.Debug("Entry skipped: SPY price unavailable")
            return

        contracts = []
        for chain in data.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if (
                    contract.Right == OptionRight.Call
                    and (contract.Expiry.date() - self.Time.date()).days >= 7
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Entry skipped: no eligible option contracts in Slice")
            return

        selected_expiry = min(contract.Expiry.date() for contract in contracts)
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call strike at selected expiration")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1, tag="Bullish 5-minute SMA crossover")
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol} expiry {selected.Expiry.date()} "
            f"strike {selected.Strike}"
        )

    def EvaluateExits(self, data):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0 or self.exit_order_id is not None:
            return

        expiry_date = self.held_option.ID.Date.date()
        if self.Time.date() == self.PreviousTradingDay(expiry_date):
            if self.Time.time() == clock_time(15, 45):
                self.SubmitExit("15:45 pre-expiration time stop")
                return

        if self.entry_price is None or self.entry_price <= 0:
            return

        if not data.QuoteBars.ContainsKey(self.held_option):
            return

        quote = data.QuoteBars[self.held_option]
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason):
        if self.held_option is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_option):
            self.Transactions.CancelOrder(order.Id)

        ticket = self.MarketOrder(self.held_option, -quantity, tag=reason)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {self.held_option} ({reason})")

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, clock_time.min)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def SyncOptionState(self):
        if self.held_option is None:
            return

        if self.Portfolio[self.held_option].Quantity == 0:
            self.held_option = None
            self.entry_price = None
            self.exit_order_id = None

    def HandleUnexpectedSpyEquity(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug(f"Unexpected SPY exercise/assignment position: {quantity}; liquidating")
            self.MarketOrder(self.spy, -quantity, tag="Unexpected exercise/assignment cleanup")

    def OnOrderEvent(self, orderEvent):
        if orderEvent.OrderId == self.entry_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.held_option = orderEvent.Symbol
                self.entry_price = orderEvent.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {orderEvent.Symbol} at {orderEvent.FillPrice}"
                )
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.Debug(f"Entry order closed without fill: {orderEvent.Symbol}")

        if orderEvent.OrderId == self.exit_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {orderEvent.Symbol} at {orderEvent.FillPrice}"
                )
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None
                self.Debug(f"Exit order closed without fill: {orderEvent.Symbol}")

